[CmdletBinding()]param([string]$CheckerPath='tools/check-self-email-boundary.ps1')
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
$repoRoot=(& git rev-parse --show-toplevel 2>$null).Trim();if($LASTEXITCODE-ne 0-or[string]::IsNullOrWhiteSpace($repoRoot)){throw'Run inside the repository.'}
function Resolve-Repo([string]$p){if([IO.Path]::IsPathRooted($p)){[IO.Path]::GetFullPath($p)}else{[IO.Path]::GetFullPath((Join-Path $repoRoot $p))}}
$checker=Resolve-Repo $CheckerPath
$inputs=@('contracts/selfemail/self-email-boundary.json','docs/adr/ADR-013-self-email.md','docs/threat-model/self-email.md','docs/prd-traceability.md','docs/product-spec.md','docs/implementation-plan.md','contracts/governance/capabilities.json','docs/adr/ADR-003-incremental-authorization.md','docs/adr/ADR-004-synchronization.md','docs/adr/ADR-005-persistence-and-cryptography.md','docs/adr/ADR-009-reminder-adapters.md','docs/adr/ADR-PRIV-001-derived-metadata-and-source-boundary.md','contracts/support/support-matrix.json','contracts/build-skeleton/skeleton.json','contracts/domain/policy-state-boundary.json','contracts/reminder/adapter-boundary.json','contracts/addin/bridge-boundary.json','contracts/automation/evaluation-boundary.json','contracts/distribution/registration-boundary.json')
$script:count=0;$script:fail=[Collections.Generic.List[string]]::new()
function New-Root{$root=Join-Path ([IO.Path]::GetTempPath()) ('openloops-selfemail-'+[guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($root)|Out-Null;foreach($rel in $inputs){$target=Join-Path $root $rel;[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($target))|Out-Null;Copy-Item -LiteralPath (Join-Path $repoRoot $rel) -Destination $target};$root}
function Check([string]$root){$a=@('-NoProfile','-File',$checker,'-ManifestPath',(Join-Path $root 'contracts/selfemail/self-email-boundary.json'),'-AdrPath',(Join-Path $root 'docs/adr/ADR-013-self-email.md'),'-ThreatPath',(Join-Path $root 'docs/threat-model/self-email.md'),'-TraceabilityPath',(Join-Path $root 'docs/prd-traceability.md'),'-ProductSpecPath',(Join-Path $root 'docs/product-spec.md'),'-ImplementationPlanPath',(Join-Path $root 'docs/implementation-plan.md'),'-GovernancePath',(Join-Path $root 'contracts/governance/capabilities.json'),'-Adr003Path',(Join-Path $root 'docs/adr/ADR-003-incremental-authorization.md'),'-Adr004Path',(Join-Path $root 'docs/adr/ADR-004-synchronization.md'),'-Adr005Path',(Join-Path $root 'docs/adr/ADR-005-persistence-and-cryptography.md'),'-Adr009Path',(Join-Path $root 'docs/adr/ADR-009-reminder-adapters.md'),'-AdrPrivPath',(Join-Path $root 'docs/adr/ADR-PRIV-001-derived-metadata-and-source-boundary.md'),'-SupportPath',(Join-Path $root 'contracts/support/support-matrix.json'),'-BuildPath',(Join-Path $root 'contracts/build-skeleton/skeleton.json'),'-PolicyPath',(Join-Path $root 'contracts/domain/policy-state-boundary.json'),'-ReminderPath',(Join-Path $root 'contracts/reminder/adapter-boundary.json'),'-AddinPath',(Join-Path $root 'contracts/addin/bridge-boundary.json'),'-AutomationPath',(Join-Path $root 'contracts/automation/evaluation-boundary.json'),'-DistributionPath',(Join-Path $root 'contracts/distribution/registration-boundary.json'),'-Quiet');$o=@(& pwsh @a 2>&1|ForEach-Object{[string]$_});[pscustomobject]@{Code=$LASTEXITCODE;Output=($o-join"`n")}}
function JsonCase([string]$name,[string]$id,[string]$rel,[scriptblock]$mutate){$script:count++;$root=New-Root;try{$path=Join-Path $root $rel;$v=Get-Content -Raw -LiteralPath $path|ConvertFrom-Json -Depth 100;&$mutate $v;$v|ConvertTo-Json -Depth 100|Set-Content -LiteralPath $path -Encoding utf8NoBOM;$r=Check $root;if($r.Code-eq 0-or$r.Output-notmatch[regex]::Escape($id)){$script:fail.Add("$name (expected $id; exit $($r.Code))")}}finally{Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue}}
function TextCase([string]$name,[string]$id,[string]$rel,[scriptblock]$mutate){$script:count++;$root=New-Root;try{$path=Join-Path $root $rel;$changed=&$mutate (Get-Content -Raw -LiteralPath $path);Set-Content -LiteralPath $path -Value $changed -Encoding utf8NoBOM;$r=Check $root;if($r.Code-eq 0-or$r.Output-notmatch[regex]::Escape($id)){$script:fail.Add("$name (expected $id; exit $($r.Code))")}}finally{Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue}}
$base=& pwsh -NoProfile -File $checker 2>&1;if($LASTEXITCODE-ne 0){throw('Baseline self-email checker failed: '+(@($base)-join"`n"))}

# Recipient policy
JsonCase 'second recipient added' 'P0-SELFMAIL-RECIPIENT-001' 'contracts/selfemail/self-email-boundary.json' {param($c)$c.recipient_policy.legal_recipient='the authenticated account and a configured backup address both receive the summary'}
JsonCase 'cc added to prohibited list removed' 'P0-SELFMAIL-RECIPIENT-001' 'contracts/selfemail/self-email-boundary.json' {param($c)$c.recipient_policy.prohibited=@($c.recipient_policy.prohibited|Where-Object{$_ -ne 'Cc'})}
JsonCase 'bcc prohibition removed' 'P0-SELFMAIL-RECIPIENT-001' 'contracts/selfemail/self-email-boundary.json' {param($c)$c.recipient_policy.prohibited=@($c.recipient_policy.prohibited|Where-Object{$_ -ne 'Bcc'})}
