JsonCase 'reply-to redirection permitted' 'P0-SELFMAIL-RECIPIENT-001' 'contracts/selfemail/self-email-boundary.json' {param($c)$c.recipient_policy.prohibited=@($c.recipient_policy.prohibited|Where-Object{$_ -ne 'reply-to redirection'})}
JsonCase 'distribution list permitted' 'P0-SELFMAIL-RECIPIENT-001' 'contracts/selfemail/self-email-boundary.json' {param($c)$c.recipient_policy.prohibited=@($c.recipient_policy.prohibited|Where-Object{$_ -ne 'distribution lists'})}
JsonCase 'canonical recipient source guessed ahead of gate' 'P0-SELFMAIL-RECIPIENT-001' 'contracts/selfemail/self-email-boundary.json' {param($c)$c.recipient_policy.canonical_source='graph_me_mail_field is the selected canonical source'}
JsonCase 'canonical recipient candidate catalog narrowed' 'P0-SELFMAIL-RECIPIENT-001' 'contracts/selfemail/self-email-boundary.json' {param($c)$c.catalogs.canonical_recipient_source_candidate_code=@($c.catalogs.canonical_recipient_source_candidate_code|Where-Object{$_ -ne 'primary_smtp_proxy_address'})}
JsonCase 'recipient policy catalog narrowed' 'P0-SELFMAIL-RECIPIENT-001' 'contracts/selfemail/self-email-boundary.json' {param($c)$c.catalogs.recipient_policy_code=@($c.catalogs.recipient_policy_code|Where-Object{$_ -ne 'no_distribution_list'})}

